cat > /etc/nginx/nginx.conf <<'ANTRIEB_NGINX'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log notice;
pid /run/nginx.pid;
events { worker_connections 1024; }
http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" upstream=$upstream_addr';
    access_log /var/log/nginx/access.log main;
    sendfile on;
    upstream inventory_backends {
        server 10.100.144.11:8080 max_fails=2 fail_timeout=5s;
        server 10.100.144.12:8080 max_fails=2 fail_timeout=5s;
    }
    server {
        listen 0.0.0.0:80 default_server;
        server_name _;
        location / {
            proxy_pass http://inventory_backends;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header Connection "";
            proxy_connect_timeout 2s;
            proxy_read_timeout 5s;
            proxy_next_upstream error timeout http_502 http_503 http_504;
        }
    }
}
